<template>
  <div><nav class="breadcrumbs"><RouterLink to="/admin/products">商品管理</RouterLink><span>/</span><span>{{ isNew ? '新增商品' : '编辑商品' }}</span></nav><div class="catalog-heading"><div><h1>{{ isNew ? '新增商品' : '编辑商品' }}</h1><p class="muted">{{ isNew ? '新商品保存后为下架状态，可在商品列表上架。' : '保存商品信息及各规格库存。' }}</p></div><RouterLink class="secondary-button" to="/admin/products">返回列表</RouterLink></div>
    <PageStatus :loading="loading" :error="loadError" @retry="load" />
    <form v-if="!loading && !loadError" class="product-editor" @submit.prevent="save">
      <section class="editor-section"><h2><span>01</span> 基本信息</h2><div class="address-fields"><label class="form-field">商品名称<input v-model.trim="form.name" required maxlength="100" placeholder="例如：烟台红富士苹果"></label><label class="form-field">商品分类<select v-model.number="form.categoryId" required><option :value="0" disabled>请选择二级分类</option><optgroup v-for="root in tree" :key="root.id" :label="root.name + (!root.status ? '（停用）' : '')"><option v-for="child in root.children" :key="child.id" :value="child.id">{{ child.name }}{{ !child.status || !root.status ? '（停用）' : '' }}</option></optgroup></select></label><label class="form-field">产地<input v-model="form.origin" maxlength="500" placeholder="例如：山东烟台"></label><label class="form-field">口感特点<input v-model="form.taste" maxlength="500" placeholder="例如：清甜爽脆"></label><label class="form-field address-field-wide">储存方法<input v-model="form.storageMethod" maxlength="500" placeholder="填写储存建议"></label><label class="form-field address-field-wide">商品描述<textarea v-model="form.description" rows="5" maxlength="5000" placeholder="介绍水果特点、包装和其他信息"></textarea></label></div></section>
      <section class="editor-section"><div class="catalog-heading"><h2><span>02</span> 商品图片</h2><label class="secondary-button upload-label">{{ uploading ? '正在上传…' : '＋ 上传图片' }}<input class="visually-hidden" type="file" accept="image/jpeg,image/png,image/webp" multiple :disabled="uploading || images.length >= 10" @change="upload"></label></div><p class="field-hint">第一张为主图。支持 JPEG、PNG、WebP，单张不超过 5 MiB，最多 10 张。</p><div class="editor-images"><div v-for="(image, index) in images" :key="image.id" class="editor-image"><img :src="imageUrl(image.url)" :alt="'商品图片 ' + (index + 1)"><span v-if="index === 0" class="main-image-label">主图</span><div><button type="button" class="text-action" :disabled="index === 0" @click="move(index, -1)">前移</button><button type="button" class="text-action" :disabled="index === images.length - 1" @click="move(index, 1)">后移</button><button type="button" class="text-action danger-text" @click="images.splice(index, 1)">移除</button></div></div></div>
        <details v-if="retainedImages.length"><summary>选用之前的图片</summary><div class="retained-images"><button v-for="image in retainedImages.filter(i => !images.some(selected => selected.id === i.id))" :key="image.id" type="button" :disabled="images.length >= 10" @click="images.push(image)"><img :src="imageUrl(image.url)" alt="保留的商品图片"><span>加入图库</span></button></div></details><p v-if="uploadError" class="form-message-error" role="alert">{{ uploadError }}</p>
      </section>
      <section class="editor-section"><div class="catalog-heading"><h2><span>03</span> 规格与库存</h2><button type="button" class="secondary-button" :disabled="form.skus.length >= 20" @click="addSku">＋ 添加规格</button></div><p class="field-hint">每种规格独立定价和库存；停用规格保留历史数据，可再次启用。</p><div class="table-scroll"><table class="admin-table sku-table"><thead><tr><th>规格名称</th><th>售价（元）</th><th>实物库存</th><th>预留 / 可售</th><th>低库存阈值</th><th>状态 / 操作</th></tr></thead><tbody><tr v-for="(sku, index) in form.skus" :key="sku.id ?? 'new-' + index" :class="{ 'inactive-sku': sku.status === 0 }"><td><input v-model.trim="sku.specification" required maxlength="100" aria-label="规格名称" placeholder="例如 500g"></td><td><input v-model="sku.price" required type="number" min="0.01" max="99999999.99" step="0.01" aria-label="规格价格"></td><td><input v-model.number="sku.onHand" required type="number" :min="sku.reserved ?? 0" max="2147483647" step="1" aria-label="实物库存"></td><td class="nowrap">{{ sku.reserved ?? 0 }} / {{ sku.onHand - (sku.reserved ?? 0) }}<small v-if="sku.status && sku.onHand - (sku.reserved ?? 0) < sku.lowStockThreshold" class="low-stock-label">低库存</small></td><td><input v-model.number="sku.lowStockThreshold" required type="number" min="0" max="2147483647" step="1" aria-label="低库存阈值"></td><td><div class="table-actions"><button v-if="sku.id" type="button" class="text-action" @click="sku.status = sku.status ? 0 : 1">{{ sku.status ? '停用' : '恢复启用' }}</button><button v-else type="button" class="text-action danger-text" :disabled="form.skus.length <= 1" @click="form.skus.splice(index, 1)">移除</button></div></td></tr></tbody></table></div><label class="form-field stock-reason">库存调整原因（选填）<input v-model="form.adjustmentReason" maxlength="200" placeholder="例如：核对库存后调整"></label></section>
      <section class="editor-section"><h2><span>04</span> 首页推荐</h2><div class="recommendation-fields"><label class="checkbox-field"><input v-model="form.recommended" type="checkbox">推荐到首页</label><label class="form-field">推荐排序<input v-model.number="form.recommendSort" type="number" min="0" max="2147483647" step="1" required><small class="field-hint">数值越小越靠前</small></label></div></section>
      <p v-if="error" class="form-message-error" role="alert">{{ error }}</p><div class="editor-submit"><button class="primary-button" :disabled="saving || uploading">{{ saving ? '正在保存…' : '保存商品' }}</button><button v-if="conflict" type="button" class="secondary-button" @click="reload">重新读取服务器信息</button><RouterLink class="text-action" to="/admin/products">取消</RouterLink></div>
    </form>
  </div>
</template>
<script setup lang="ts">
import { ref, reactive, computed, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import axios from 'axios'
import { ElMessageBox } from 'element-plus'
import 'element-plus/es/components/message-box/style/css'
import PageStatus from '../components/PageStatus.vue'
import { adminCategories, adminProduct, saveProduct, uploadProductImage, type ProductPayload, type AdminSku } from '../api/admin-catalog'
import { imageUrl, errorMessage, type Category, type ImageRef } from '../api/catalog'
const route = useRoute(), router = useRouter(), isNew = computed(() => !route.params.productId)
const tree = ref<Category[]>([]), images = ref<ImageRef[]>([]), retainedImages = ref<ImageRef[]>([]), loading = ref(false), loadError = ref(''), saving = ref(false), uploading = ref(false), uploadError = ref(''), error = ref(''), conflict = ref(false)
const freshSku = (): AdminSku => ({ specification: '默认规格', price: '', onHand: 0, lowStockThreshold: 0, status: 1 })
const form = reactive<ProductPayload>({ name: '', categoryId: 0, description: '', origin: '', taste: '', storageMethod: '', recommended: false, recommendSort: 0, imageIds: [], skus: [freshSku()], adjustmentReason: '' })
async function load() { loading.value = true; loadError.value = ''; error.value = ''; conflict.value = false; images.value = []; retainedImages.value = []; try { tree.value = await adminCategories(); if (!isNew.value) { const p = await adminProduct(Number(route.params.productId)); Object.assign(form, { name: p.name, categoryId: p.categoryId, description: p.description, origin: p.origin, taste: p.taste, storageMethod: p.storageMethod, recommended: p.recommended, recommendSort: p.recommendSort, version: p.version, skus: p.skus.map(s => ({ ...s })), adjustmentReason: '' }); images.value = p.images; retainedImages.value = p.retainedImages } else { Object.assign(form, { name: '', categoryId: 0, description: '', origin: '', taste: '', storageMethod: '', recommended: false, recommendSort: 0, version: undefined, skus: [freshSku()], adjustmentReason: '' }) } } catch (e) { loadError.value = errorMessage(e) } finally { loading.value = false } }
function addSku() { form.skus.push({ ...freshSku(), specification: '' }) }
function move(index: number, direction: number) { const entry = images.value.splice(index, 1)[0]; if (entry) images.value.splice(index + direction, 0, entry) }
async function upload(event: Event) { const input = event.target as HTMLInputElement, files = Array.from(input.files ?? []); input.value = ''; uploadError.value = ''; if (images.value.length + files.length > 10) { uploadError.value = '每个商品最多 10 张图片'; return } uploading.value = true; try { for (const file of files) { if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type) || file.size > 5 * 1024 * 1024) { uploadError.value = '仅支持不超过 5 MiB 的 JPEG、PNG 或 WebP 图片'; break } images.value.push(await uploadProductImage(file)) } } catch (e) { uploadError.value = errorMessage(e) } finally { uploading.value = false } }
async function save() { error.value = ''; conflict.value = false; const names = new Set<string>(); for (const sku of form.skus) { if (!sku.specification.trim() || names.has(sku.specification.trim())) { error.value = '规格名称不能为空或重复'; return } names.add(sku.specification.trim()); if (!/^\d{1,8}(\.\d{1,2})?$/.test(String(sku.price)) || Number(sku.price) <= 0) { error.value = '售价必须大于 0 且最多两位小数'; return } if (!Number.isInteger(sku.onHand) || !Number.isInteger(sku.lowStockThreshold) || sku.onHand < (sku.reserved ?? 0) || sku.lowStockThreshold < 0) { error.value = '库存和阈值必须为非负整数，实物库存不得低于预留量'; return } } if (!form.categoryId) { error.value = '请选择二级分类'; return } saving.value = true; try { const payload: ProductPayload = { ...form, imageIds: images.value.map(i => i.id), skus: form.skus.map(s => ({ id: s.id, specification: s.specification, price: String(s.price), onHand: s.onHand, lowStockThreshold: s.lowStockThreshold, status: s.status, inventoryVersion: s.inventoryVersion })) }; await saveProduct(isNew.value ? null : Number(route.params.productId), payload); await router.push('/admin/products') } catch (e) { error.value = errorMessage(e); conflict.value = axios.isAxiosError(e) && e.response?.status === 409 } finally { saving.value = false } }
async function reload() { try { await ElMessageBox.confirm('重新读取将替换当前草稿，确认继续？', '重新读取', { confirmButtonText: '读取', cancelButtonText: '保留草稿' }); await load() } catch { return } }
watch(() => route.params.productId, load, { immediate: true })
</script>
